<?php require_once 'header.php'; function erfe($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}$isEdit=!empty($record);$fields=array('emr_sent_count'=>'Số bệnh án đã gửi lên EMR','emr_signed_count'=>'Số bệnh án đã hoàn thành chữ ký','emr_signed_unarchived_count'=>'Đã ký nhưng chưa lưu trữ','emr_archived_count'=>'Số bệnh án đã lưu trữ','emr_archive_due_count'=>'Số bệnh án lưu trữ chậm','emr_archive_on_time_count'=>'Số bệnh án lưu trữ đúng hạn'); ?>
<main class="content-body"><section class="page-section"><div class="section-title-bar"><div class="section-title"><i class="fa-solid fa-file-waveform"></i> <?php echo $isEdit?'Sửa số liệu EMR':'Nhập số liệu EMR'; ?></div><a href="<?php echo XC_URL; ?>/backend/emrReport" class="btn btn-outline"><i class="fa-solid fa-arrow-left"></i> Quay lại</a></div>
<?php if(!$isEdit): ?><div class="card" style="margin-bottom:18px"><div class="card-header"><div class="card-title"><i class="fa-solid fa-file-import"></i> Import số liệu</div></div><div class="card-body"><form id="emrReportImportForm" enctype="multipart/form-data" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?php echo erfe($csrf); ?>"><input type="file" name="import_file" accept=".xlsx,.csv" required><a class="btn btn-outline" href="<?php echo XC_URL; ?>/backend/emrReport/template"><i class="fa-solid fa-download"></i> Tải file mẫu</a><span style="font-size:12px;color:var(--text-muted)">Cột Ngày ghi nhận là bắt buộc. Tối đa 5 MB.</span><button class="btn btn-success"><i class="fa-solid fa-upload"></i> Import</button></form></div></div><?php endif; ?>
<div class="card"><div class="card-body"><form id="emrReportForm" class="form-grid" novalidate><input type="hidden" name="csrf" value="<?php echo erfe($csrf); ?>"><input type="hidden" name="id" value="<?php echo $isEdit?(int)$record->id:''; ?>"><div class="form-group"><label class="form-label">Ngày ghi nhận <span class="req">*</span></label><select class="form-select" name="report_date" required><option value="">Chọn ngày</option><?php foreach($reportDates as $date): ?><option value="<?php echo (int)$date->id; ?>" <?php echo $isEdit?((int)$record->report_date===(int)$date->id?'selected':''):($date->full_date===date('Y-m-d')?'selected':''); ?>><?php echo erfe(date('d/m/Y',strtotime($date->full_date))); ?></option><?php endforeach; ?></select></div><?php foreach($fields as $key=>$label): ?><div class="form-group"><label class="form-label"><?php echo $label; ?></label><input class="form-control" type="number" min="0" max="4294967295" step="1" name="<?php echo $key; ?>" value="<?php echo $isEdit?(int)$record->$key:0; ?>" required></div><?php endforeach; ?><div class="form-group" style="grid-column:1/-1"><label class="form-label">Ghi chú</label><textarea class="form-control" name="note" rows="3" maxlength="5000" placeholder="Nội dung đối soát, điều chỉnh hoặc quy tắc xác định hạn lưu trữ"><?php echo $isEdit?erfe($record->note):''; ?></textarea></div><div class="form-actions" style="grid-column:1/-1"><a class="btn btn-outline" href="<?php echo XC_URL; ?>/backend/emrReport">Hủy</a><button class="btn btn-primary"><i class="fa-solid fa-floppy-disk"></i> <?php echo $isEdit?'Cập nhật':'Lưu số liệu'; ?></button></div></form></div></div>
</section></main>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script>(function($){function showResult(response,redirect){Swal.fire({icon:response.success?'success':'error',title:response.success?'Thành công':'Không thành công',text:response.message,timer:response.success?1500:0,showConfirmButton:!response.success}).then(function(){if(response.success&&redirect)location.href='<?php echo XC_URL; ?>/backend/emrReport';});}function send(form,action,multipart){if(!multipart&&!form.checkValidity()){form.reportValidity();return;}var button=$(form).find('button').prop('disabled',true),options={url:'<?php echo XC_URL; ?>/api/'+action,type:'POST',dataType:'json',data:multipart?new FormData(form):$(form).serialize()};if(multipart){options.processData=false;options.contentType=false;}$.ajax(options).done(function(response){showResult(response,!multipart||response.success);if(multipart&&response.success)$(form).find('input[type=file]').val('');}).fail(function(xhr){Swal.fire('Không thành công',(xhr.responseJSON&&xhr.responseJSON.message)||'Không thể kết nối máy chủ. Vui lòng thử lại.','error');}).always(function(){button.prop('disabled',false);});}$('#emrReportForm').on('submit',function(e){e.preventDefault();send(this,'<?php echo $isEdit?'editEmrReport':'saveEmrReport'; ?>',false);});$('#emrReportImportForm').on('submit',function(e){e.preventDefault();var file=this.import_file.files[0];if(!file||!/\.(xlsx|csv)$/i.test(file.name)||file.size<1||file.size>5*1024*1024){Swal.fire('Tệp không hợp lệ','Chọn tệp .xlsx hoặc .csv không quá 5 MB.','error');return;}send(this,'importEmrReport',true);});})(jQuery);</script>
